import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function Header({ title, onBack }) {
  return (
    <View nativeID="header" style={styles.header}>
      {onBack ? (
        <Pressable nativeID="hback" onPress={onBack}>
          <Text style={styles.arrow}>←</Text>
        </Pressable>
      ) : null}
      <Text nativeID="htitle" style={styles.htitle}>{title}</Text>
    </View>
  );
}

function App() {
  const [screen, setScreen] = useState("list");
  if (screen === "detail") {
    return (
      <View style={styles.screen}>
        {/* энд бичнэ үү: Header-т onBack дамжуулж буцах товч гарга */}
        <Header title="Дэлгэрэнгүй" />
        <Text>Утасгүй чихэвч</Text>
      </View>
    );
  }
  return (
    <View style={styles.screen}>
      <Header title="Shop.mn" />
      <Pressable nativeID="open" style={styles.btn} onPress={() => setScreen("detail")}>
        <Text style={styles.btnText}>Дэлгэрэнгүй үзэх</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1 },
  header: { flexDirection: "row", alignItems: "center", gap: 12, padding: 16, backgroundColor: "#2563eb" },
  arrow: { color: "#fff", fontSize: 22, fontWeight: "bold" },
  htitle: { color: "#fff", fontSize: 18, fontWeight: "bold" },
  btn: { margin: 16, backgroundColor: "#2563eb", padding: 14, borderRadius: 12, alignItems: "center" },
  btnText: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);

